fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Compute the ceiling of health / strength using integer arithmetic:
    // (health + strength - 1) / strength
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Number of turns Takahashi needs to defeat Aoki
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // Number of turns Aoki needs to defeat Takahashi
    let aoki_turns = exec_turns_to_defeat(a, d);

    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

